fn diag_val(i: isize, j: isize) -> f64 {
    if i == j {
        1.0
    } else {
        0.0
    }
}

fn identity(n: usize) -> Vec<Vec<f64>> {
    let mut mat: Vec<Vec<f64>> = Vec::with_capacity(n);
    for i in 0..n {
        let mut row: Vec<f64> = Vec::with_capacity(n);
        for j in 0..n {
            // cast i and j to isize for diag_val
            row.push(diag_val(i as isize, j as isize));
        }
        mat.push(row);
    }
    mat
}

fn main() {
    // Example usage:
    let m0 = identity(0);
    assert_eq!(m0.len(), 0);

    let m1 = identity(1);
    assert_eq!(m1, vec![vec![1.0]]);

    let m4 = identity(4);
    assert_eq!(
        m4,
        vec![
            vec![1.0, 0.0, 0.0, 0.0],
            vec![0.0, 1.0, 0.0, 0.0],
            vec![0.0, 0.0, 1.0, 0.0],
            vec![0.0, 0.0, 0.0, 1.0],
        ]
    );
}